import calendar
import re
from datetime import date

_MONTHS = {}
for _i in range(1, 13):
    _MONTHS[calendar.month_name[_i].lower()] = _i
    _MONTHS[calendar.month_abbr[_i].lower()] = _i
_MONTHS["sept"] = 9

_ORDINAL = r"(?:st|nd|rd|th)?"

# Optional leading weekday, e.g. "Tuesday, ", "Tue. ", "thurs "
_WEEKDAY = re.compile(
    r"^(?:monday|tuesday|wednesday|thursday|friday|saturday|sunday"
    r"|mon|tues?|wed|thu|thur|thurs|fri|sat|sun)\.?(?:,\s*|\s+)"
)

# YYYY<sep>MM<sep>DD, e.g. 2024-03-05, 2022/11/30, 2024.3.5
_YMD = re.compile(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})")

# DD<sep>MM<sep>YYYY (day-first), e.g. 05/03/2024 -> 2024-03-05
_DMY = re.compile(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})")

# 5 March 2024, 5th of March, 5-Mar-2024
_D_MON_Y = re.compile(
    r"(\d{1,2})" + _ORDINAL + r"(?:\s+of)?[\s-]+([a-z]+)\.?,?[\s-]+(\d{4})"
)

# March 5, 2024 / Mar 5th 2024 / March, 5 2024
_MON_D_Y = re.compile(
    r"([a-z]+)\.?,?[\s-]+(\d{1,2})" + _ORDINAL + r",?[\s-]+(\d{4})"
)


def _build(year: int, month: int, day: int):
    try:
        return date(year, month, day).isoformat()
    except (ValueError, OverflowError):
        return None


def _month_number(name: str):
    return _MONTHS.get(name)


def _normalize(s: str) -> str:
    text = " ".join(s.strip().split()).lower()
    return _WEEKDAY.sub("", text, count=1)


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    text = _normalize(s)
    if not text:
        return "INVALID"

    result = None

    m = _YMD.fullmatch(text)
    if m:
        y, _, mo, d = m.groups()
        result = _build(int(y), int(mo), int(d))
    else:
        m = _DMY.fullmatch(text)
        if m:
            d, _, mo, y = m.groups()
            result = _build(int(y), int(mo), int(d))
        else:
            m = _D_MON_Y.fullmatch(text)
            if m:
                d, mon, y = m.groups()
                mo = _month_number(mon)
                if mo is not None:
                    result = _build(int(y), mo, int(d))
            else:
                m = _MON_D_Y.fullmatch(text)
                if m:
                    mon, d, y = m.groups()
                    mo = _month_number(mon)
                    if mo is not None:
                        result = _build(int(y), mo, int(d))

    return result if result is not None else "INVALID"

import re
from datetime import date

INVALID = "INVALID"

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

_WEEKDAYS = {
    "monday", "mon",
    "tuesday", "tue", "tues",
    "wednesday", "wed",
    "thursday", "thu", "thur", "thurs",
    "friday", "fri",
    "saturday", "sat",
    "sunday", "sun",
}


def _to_iso(year: int, month: int, day: int) -> str:
    """Validate the components (including leap years) and format as ISO."""
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return INVALID


def _resolve_numeric(a: int, b: int) -> tuple[int, int]:
    """
    Resolve an ambiguous pair of numeric date parts to (month, day).
    - If the second part can't be a month but the first can, it must be MM/DD.
    - Otherwise assume day-first (DD/MM), matching the observed convention.
    """
    if b > 12 and a <= 12:
        return a, b
    return b, a


def _strip_weekdays(t: str) -> str:
    """Remove weekday names (e.g. 'Tuesday,') since they carry no date info."""
    kept = [tok for tok in t.split() if tok.rstrip(".") not in _WEEKDAYS]
    return " ".join(kept)


def parse(s: str) -> str:
    if not isinstance(s, str):
        return INVALID

    t = s.strip().lower()
    if not t:
        return INVALID

    # Drop ordinal suffixes (1st, 2nd, 3rd, 4th) and normalize commas/whitespace.
    t = re.sub(r"(\d)(st|nd|rd|th)\b", r"\1", t)
    t = re.sub(r"\s*,\s*", " ", t)
    t = re.sub(r"\s+", " ", t).strip()

    # Remove weekday names anywhere in the string.
    t = _strip_weekdays(t)
    if not t:
        return INVALID

    # YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD (separator must be consistent)
    m = re.fullmatch(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})", t)
    if m:
        return _to_iso(int(m.group(1)), int(m.group(3)), int(m.group(4)))

    # Compact YYYYMMDD
    m = re.fullmatch(r"(\d{4})(\d{2})(\d{2})", t)
    if m:
        return _to_iso(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # Numeric with year last: A?B?YYYY using -, /, or . as separator
    m = re.fullmatch(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})", t)
    if m:
        a, b, year = int(m.group(1)), int(m.group(3)), int(m.group(4))
        month, day = _resolve_numeric(a, b)
        return _to_iso(year, month, day)

    # Month-name forms: "March 5 2021", "5 March 2021", "5-Mar-2021", "2021 Mar 5"
    if re.search(r"[a-z]", t):
        parts = [p for p in re.split(r"[\s\-/.]+", t) if p]
        if len(parts) != 3:
            return INVALID

        names = [p for p in parts if p.isalpha()]
        nums = [p for p in parts if p.isdigit()]
        if len(names) != 1 or len(nums) != 2:
            return INVALID

        month = _MONTHS.get(names[0])
        if month is None:
            return INVALID

        years = [n for n in nums if len(n) == 4]
        days = [n for n in nums if 1 <= len(n) <= 2]
        if len(years) != 1 or len(days) != 1:
            return INVALID

        return _to_iso(int(years[0]), month, int(days[0]))

    return INVALID

import re
from datetime import date

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
