    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

# Longer alternatives first so full names match before abbreviations.
_WEEKDAY = (
    r"(?:monday|mon|tuesday|tues|tue|wednesday|wed|thursday|thurs|thur|thu|"
    r"friday|fri|saturday|sat|sunday|sun)"
)

_ORD = r"(?:st|nd|rd|th)?"


def _build(year: int, month: int, day: int) -> str:
    try:
        return date(year, month, day).isoformat()
    except ValueError:
        return "INVALID"


def _normalize(s: str) -> str:
    # Lowercase, treat commas as spaces, collapse whitespace.
    t = s.lower().replace(",", " ")
    t = re.sub(r"\s+", " ", t).strip()
    # Strip one leading or trailing weekday name.
    t = re.sub(r"^" + _WEEKDAY + r"\.?\s+", "", t)
    t = re.sub(r"\s+" + _WEEKDAY + r"\.?$", "", t)
    return t.strip()


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    t = _normalize(s)
    if not t:
        return "INVALID"

    # ISO-like: YYYY-MM-DD, YYYY/MM/DD, YYYY.MM.DD
    m = re.fullmatch(r"(\d{4})[-/.](\d{1,2})[-/.](\d{1,2})", t)
    if m:
        return _build(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # Compact: YYYYMMDD
    m = re.fullmatch(r"(\d{4})(\d{2})(\d{2})", t)
    if m:
        return _build(int(m.group(1)), int(m.group(2)), int(m.group(3)))

    # Numeric day-first: DD/MM/YYYY, DD-MM-YYYY, DD.MM.YYYY
    m = re.fullmatch(r"(\d{1,2})[/.\-](\d{1,2})[/.\-](\d{4})", t)
    if m:
        return _build(int(m.group(3)), int(m.group(2)), int(m.group(1)))

    # Month-name first: "nov 31 2022", "november 31st 2022", "nov-31-2022"
    m = re.fullmatch(
        r"([a-z]{3,9})\.?[ \-/]*(\d{1,2})" + _ORD + r"[ \-/]*(\d{4})",
        t,
    )
    if m:
        month = _MONTHS.get(m.group(1))
        if month is None:
            return "INVALID"
        return _build(int(m.group(3)), month, int(m.group(2)))

    # Day-first with month name: "31 nov 2022", "31-nov-2022", "31st november 2022"
    m = re.fullmatch(
        r"(\d{1,2})" + _ORD + r"[ \-/.]*([a-z]{3,9})\.?[ \-/]*(\d{4})",
        t,
    )
    if m:
        month = _MONTHS.get(m.group(2))
        if month is None:
            return "INVALID"
        return _build(int(m.group(3)), month, int(m.group(1)))

    # Year-first with month name: "2022 nov 31", "2022-November-31st"
    m = re.fullmatch(
        r"(\d{4})[ \-/.]*([a-z]{3,9})\.?[ \-/]*(\d{1,2})" + _ORD,
        t,
    )
    if m:
        month = _MONTHS.get(m.group(2))
        if month is None:
            return "INVALID"
        return _build(int(m.group(1)), month, int(m.group(3)))

    return "INVALID"

import re
from datetime import date

_MONTHS = {
    "jan": 1, "january": 1,
    "feb": 2, "february": 2,
    "mar": 3, "march": 3,
    "apr": 4, "april": 4,
    "may": 5,
    "jun": 6, "june": 6,
    "jul": 7, "july": 7,
    "aug": 8, "august": 8,
    "sep": 9, "sept": 9, "september": 9,
    "oct": 10, "october": 10,
    "nov": 11, "november": 11,
    "dec": 12, "december": 12,
}

# Optional leading weekday, e.g. "Tuesday, ", "Tue. ", "Thursday "
_WEEKDAY_PREFIX = re.compile(
    r"^(?:mon(?:day)?|tue(?:s|sday)?|wed(?:nesday)?|thu(?:r|rs|rsday)?|fri(?:day)?|sat(?:urday)?|sun(?:day)?)"
    r"\.?,?\s+",
    re.IGNORECASE,
)

# Year-first numeric: 2024-03-05, 2024/3/5, 2024.03.05
_YEAR_FIRST = re.compile(r"(\d{4})([-/.])(\d{1,2})\2(\d{1,2})")

# Day-first numeric: 05/03/2024, 31-12-1999, 5.3.2024 (read as D/M/Y)
_DAY_FIRST_NUMERIC = re.compile(r"(\d{1,2})([-/.])(\d{1,2})\2(\d{4})")

# e.g. "22nd Feb 1900", "22 February, 1900", "22-Feb-1900"
_DAY_MONTH_YEAR = re.compile(
    r"(\d{1,2})(?:st|nd|rd|th)?[\s\-/.,]+([A-Za-z]+)\.?[\s\-/.,]+(\d{4})",
    re.IGNORECASE,
)

# e.g. "Feb 22, 1900", "February 22nd 1900"
_MONTH_DAY_YEAR = re.compile(
    r"([A-Za-z]+)\.?[\s\-/.,]+(\d{1,2})(?:st|nd|rd|th)?[\s\-/.,]+(\d{4})",
    re.IGNORECASE,
)


def _month_number(name: str):
    return _MONTHS.get(name.lower())


def _build(year: int, month: int, day: int) -> str:
    try:
        return date(year, month, day).isoformat()  # validates ranges and leap years
    except ValueError:
        return "INVALID"


def parse(s: str) -> str:
    if not isinstance(s, str):
        return "INVALID"

    text = " ".join(s.split())  # trim and collapse internal whitespace
    if not text:
        return "INVALID"

    # Drop a leading weekday name if present; it carries no date information.
    stripped = _WEEKDAY_PREFIX.sub("", text, count=1)
    if stripped:
        text = stripped

    m = _YEAR_FIRST.fullmatch(text)
    if m is not None:
        year, month, day = int(m.group(1)), int(m.group(3)), int(m.group(4))
        return _build(year, month, day)

    # Numeric ambiguous dates are read day-first (D/M/Y).
    m = _DAY_FIRST_NUMERIC.fullmatch(text)
    if m is not None:
        day, month, year = int(m.group(1)), int(m.group(3)), int(m.group(4))
        return _build(year, month, day)

    m = _DAY_MONTH_YEAR.fullmatch(text)
    if m is not None:
        day, month_name, year = int(m.group(1)), m.group(2), int(m.group(3))
        month = _month_number(month_name)
        if month is None:
            return "INVALID"
        return _build(year, month, day)

    m = _MONTH_DAY_YEAR.fullmatch(text)
    if m is not None:
        month_name, day, year = m.group(1), int(m.group(2)), int(m.group(3))
        month = _month_number(month_name)
        if month is None:
            return "INVALID"
        return _build(year, month, day)

    return "INVALID"
